<?php
use PHPUnit\Framework\TestCase;
final class Phase9FlatRateAdminTest extends TestCase {
 public function test_flat_rate_capabilities_are_company_capabilities(): void {$c=file_get_contents(__DIR__.'/../../src/Users/Capabilities.php');$this->assertStringContainsString("VIEW_FLAT_RATE = 'servsys_view_flat_rate'",$c);$this->assertStringContainsString("MANAGE_FLAT_RATE = 'servsys_manage_flat_rate'",$c);$this->assertGreaterThanOrEqual(2,substr_count($c,'self::VIEW_FLAT_RATE'));$this->assertGreaterThanOrEqual(2,substr_count($c,'self::MANAGE_FLAT_RATE'));}
 public function test_plugin_registers_flat_rate_admin_page(): void {$p=file_get_contents(__DIR__.'/../../src/Plugin.php');$this->assertStringContainsString('use ServSys\\Admin\\FlatRatePage;',$p);$this->assertStringContainsString('( new FlatRatePage() )->register();',$p);}
 public function test_configuration_links_to_flat_rate_admin(): void {$p=file_get_contents(__DIR__.'/../../src/Admin/ConfigurationPage.php');$this->assertStringContainsString('Capabilities::VIEW_FLAT_RATE',$p);$this->assertStringContainsString("'servsys-flat-rate'",$p);}
 public function test_admin_writes_require_nonces_and_manage_capability(): void {$p=file_get_contents(__DIR__.'/../../src/Admin/FlatRatePage.php');foreach(array('servsys_save_flat_rate_config','servsys_save_flat_rate_category','servsys_save_flat_rate_item') as $nonce){$this->assertStringContainsString($nonce,$p);}$this->assertStringContainsString('check_admin_referer($nonce)',$p);$this->assertStringContainsString('Capabilities::MANAGE_FLAT_RATE',$p);}
 public function test_flat_rate_repositories_scope_queries_and_writes_to_company_context(): void {foreach(array('FlatRateConfigRepository.php','FlatRateCategoryRepository.php','FlatRateItemRepository.php','FlatRateMaterialRepository.php') as $file){$p=file_get_contents(__DIR__.'/../../src/FlatRate/'.$file);$this->assertStringContainsString('CompanyContext::current_company_id()',$p,$file);}}
 public function test_service_validates_cross_company_category_inventory_and_item_relationships(): void {$p=file_get_contents(__DIR__.'/../../src/FlatRate/FlatRateService.php');$this->assertStringContainsString('category does not belong to the current company',$p);$this->assertStringContainsString('inventory item does not belong to the current company',$p);$this->assertStringContainsString('item does not belong to the current company',$p);$this->assertStringContainsString("START TRANSACTION",$p);$this->assertStringContainsString("ROLLBACK",$p);}
 public function test_admin_exposes_all_p9_3_surfaces(): void {$p=file_get_contents(__DIR__.'/../../src/Admin/FlatRatePage.php');foreach(array('Price Book','Categories','Pricing Configuration','Material Recipe','Search Flat Rate') as $label){$this->assertStringContainsString($label,$p);}}
}
